questionvariables.text:
sm : rand([2, 2.5, 3]);
off : rand([1, 2, 3]);
c : 6*sm + off;                 /* intercept (larger number); keeps decreasing data positive */
sgn : rand([-1, 1]);
m : sgn*sm;
y1 : round(c + m*1 + rand([-1,0,1]));
y2 : round(c + m*2 + rand([-1,0,1]));
y3 : round(c + m*3 + rand([-1,0,1]));
y4 : round(c + m*4 + rand([-1,0,1]));
y5 : round(c + m*5 + rand([-1,0,1]));
y6 : round(c + m*6 + rand([-1,0,1]));
ymaxwin : max(c, y1, y2, y3, y4, y5, y6) + 3;
o1 : c + sm*x;    /* right numbers, positive slope */
o2 : c - sm*x;    /* right numbers, negative slope */
o3 : sm + c*x;    /* swapped intercept/slope, positive */
o4 : sm - c*x;    /* swapped, negative */
correctexpr : c + m*x;
wrongsign : if is(sgn=1) then o2 else o1;
disp1 : sconcat("\\(y = ", c, " + ", sm, "x\\)");
disp2 : sconcat("\\(y = ", c, " - ", sm, "x\\)");
disp3 : sconcat("\\(y = ", sm, " + ", c, "x\\)");
disp4 : sconcat("\\(y = ", sm, " - ", c, "x\\)");
correctdisp : if is(sgn=1) then disp1 else disp2;
mcopts : random_permutation([[o1, is(sgn=1), disp1], [o2, is(sgn=-1), disp2], [o3, false, disp3], [o4, false, disp4]]);
